"""Read ids.txt (one order id per line, most recent last) and print the next order id."""

import sys


def to_base36(n: int) -> str:
    """Convert a non-negative integer to its base-36 representation (uppercase)."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n == 0:
        return chars[0]
    result = []
    while n > 0:
        result.append(chars[n % 36])
        n //= 36
    return "".join(reversed(result))


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("Error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        # No ids issued yet – start from zero
        next_suffix = "0000"
    else:
        last_id = lines[-1]
        try:
            _prefix, suffix = last_id.split("-", 1)
        except ValueError:
            print(f"Error: invalid id format: {last_id!r}", file=sys.stderr)
            sys.exit(1)

        num = int(suffix, 36)
        next_num = num + 1
        next_suffix = to_base36(next_num).zfill(4).upper()

    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

