"""Print the next order id to stdout."""

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def base36_encode(n: int) -> str:
    """Encode a non-negative integer as a base-36 string (zero-padded to 4 chars)."""
    if n == 0:
        return "0000"
    chars = []
    while n > 0:
        chars.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(chars)).rjust(4, "0")


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch)
    return n


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        print("ORD-0000")
        return

    last_line = lines[-1]
    parts = last_line.split("-", 1)
    if len(parts) != 2 or not parts[1]:
        print(f"Malformed id: {last_line!r}", file=sys.stderr)
        sys.exit(1)

    code = parts[1]
    if len(code) != 4:
        print(f"Malformed code in id: {last_line!r}", file=sys.stderr)
        sys.exit(1)

    n = base36_decode(code)
    n += 1
    next_code = base36_encode(n)
    print(f"ORD-{next_code}")


if __name__ == "__main__":
    main()

