import sys

def parse_order_id(line):
    """Extract the order id from a line, handling possible line-number prefixes."""
    # lines might look like "1\tORD-243C" or just "ORD-243C"
    line = line.strip()
    if not line:
        return None
    # Try to find ORD-XXXX pattern
    idx = line.find("ORD-")
    if idx == -1:
        return None
    return line[idx:idx+8]  # ORD- + 4 chars

def base36_to_int(s):
    """Convert a base-36 string to an integer."""
    result = 0
    for c in s:
        result = result * 36
        if '0' <= c <= '9':
            result += ord(c) - ord('0')
        elif 'A' <= c <= 'Z':
            result += ord(c) - ord('A') + 10
        elif 'a' <= c <= 'z':
            result += ord(c) - ord('a') + 10
    return result

def int_to_base36(n, width=4):
    """Convert an integer to a base-36 string of the given width."""
    chars = []
    for _ in range(width):
        chars.append("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[n % 36])
        n //= 36
    return ''.join(reversed(chars))

def main():
    try:
        with open("ids.txt", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        # If no ids.txt, start from 0000
        print("ORD-0000")
        return

    last_id = None
    for line in lines:
        oid = parse_order_id(line)
        if oid:
            last_id = oid

    if last_id is None:
        print("ORD-0000")
    else:
        suffix = last_id[4:]  # extract the 4-char suffix
        num = base36_to_int(suffix)
        next_num = num + 1
        next_suffix = int_to_base36(next_num)
        print(f"ORD-{next_suffix}")

if __name__ == "__main__":
    main()
