#!/usr/bin/env python3
"""Read ids.txt (one order id per line, most recent last) and print the next id."""

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def base36_decode(s: str) -> int:
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch.upper())
    return n


def base36_encode(n: int, width: int) -> str:
    digits = []
    for _ in range(width):
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-" + base36_encode(0, 4), file=sys.stderr)
        sys.exit(1)

    if not lines:
        print("ORD-" + base36_encode(0, 4), file=sys.stderr)
        sys.exit(1)

    last_id = lines[-1]
    if not last_id.startswith("ORD-") or len(last_id) != 8:
        print(f"Unexpected id format: {last_id!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]
    n = base36_decode(suffix) + 1
    next_suffix = base36_encode(n, 4)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

