#!/usr/bin/env python3
"""Remove duplicate events sharing an event_id from events.jsonl."""

import json

INPUT = "events.jsonl"
OUTPUT = "deduped.jsonl"

def main():
    seen = set()
    with open(INPUT, "r") as fin, open(OUTPUT, "w") as fout:
        for line in fin:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            eid = obj.get("event_id")
            if eid not in seen:
                seen.add(eid)
                fout.write(line + "\n")

    print(f"Wrote {len(seen)} unique events to {OUTPUT}")


if __name__ == "__main__":
    main()

