#!/usr/bin/env python3
"""Walk release/, compute SHA-256 per file, write manifest.json."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_PATH = "manifest.json"


def main() -> None:
    manifest = {}

    for dirpath, _dirnames, filenames in os.walk(RELEASE_DIR):
        for fn in sorted(filenames):
            path = os.path.join(dirpath, fn)
            sha256 = hashlib.sha256()
            with open(path, "rb") as f:
                while True:
                    chunk = f.read(1 << 20)  # 1 MiB
                    if not chunk:
                        break
                    sha256.update(chunk)
            manifest[path] = sha256.hexdigest()

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2, sort_keys=True)
        f.write("\n")

    print(f"wrote {len(manifest)} entries to {MANIFEST_PATH}")


if __name__ == "__main__":
    main()

