"""Generate manifest.json with SHA-256 digests for files under release/."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_PATH = "manifest.json"


def sha256_digest(filepath: str) -> str:
    """Return the SHA-256 hex digest of the given file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}
    for root, _dirs, files in os.walk(RELEASE_DIR):
        for filename in files:
            full_path = os.path.join(root, filename)
            rel_path = os.path.normpath(full_path)
            manifest[rel_path] = sha256_digest(full_path)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote {MANIFEST_PATH} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

