"""Generate manifest.json: SHA-256 digests of all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path(__file__).parent / "release"
MANIFEST_PATH = Path(__file__).parent / "manifest.json"


def sha256_digest(filepath: Path) -> str:
    """Return hex-encoded SHA-256 of the file's content."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        while True:
            chunk = f.read(65536)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        print(f"error: {RELEASE_DIR} does not exist")
        return

    manifest: dict[str, str] = {}

    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel_path = str(path.relative_to(RELEASE_DIR.parent))
            manifest[rel_path] = sha256_digest(path)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"wrote {MANIFEST_PATH} with {len(manifest)} entries")


if __name__ == "__main__":
    main()
