#!/usr/bin/env python3
"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timezone

LOG_FILE = "app.log"
ARCHIVE_FILE = "archive.log"

def parse_entry_ts(line: str) -> datetime | None:
    """Parse leading 'YYYY-MM-DD HH:MM:SS' from a log line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None

def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff_dt = datetime.fromtimestamp(as_of - 7 * 86400, tz=timezone.utc)

    with open(LOG_FILE) as f:
        lines = f.readlines()

    # Remove trailing newline for clean processing
    lines = [line.rstrip("\n") for line in lines]

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        ts = parse_entry_ts(line)
        if ts is not None and ts < cutoff_dt:
            archive.append(line)
        else:
            keep.append(line)

    if archive:
        with open(ARCHIVE_FILE, "a") as f:
            for entry in archive:
                f.write(entry + "\n")

    with open(LOG_FILE, "w") as f:
        for entry in keep:
            f.write(entry + "\n")

if __name__ == "__main__":
    main()

