import sys
import datetime

LOG_FILE = "app.log"
ARCHIVE_FILE = "archive.log"


def parse_timestamp(line: str) -> datetime.datetime | None:
    """Try to parse 'YYYY-MM-DD HH:MM:SS' from the start of a line."""
    try:
        ts_str = line[:19]
        return datetime.datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S")
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = datetime.datetime.fromtimestamp(as_of, tz=datetime.timezone.utc) - datetime.timedelta(days=7)

    try:
        with open(LOG_FILE) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"{LOG_FILE} not found", file=sys.stderr)
        sys.exit(1)

    # Strip trailing newlines for comparison, but we'll preserve original content
    keep = []
    archive = []

    for line in lines:
        dt = parse_timestamp(line)
        if dt is not None:
            # The log timestamps are naive (no timezone). Treat them as UTC.
            dt_utc = dt.replace(tzinfo=datetime.timezone.utc)
            if dt_utc < cutoff:
                archive.append(line)
            else:
                keep.append(line)
        else:
            # Lines without a parseable timestamp stay in app.log
            keep.append(line)

